import { motion, AnimatePresence } from 'framer-motion';
import { Link } from 'react-router-dom';
import styles from './UserDashboard.module.css';

const UserDashboard = () => {
  const { user, setUser, notifications, clearNotifications } = useAuth();
  const [activeTab, setActiveTab] = useState('profile');
  const [purchases, setPurchases] = useState([]);
  const [testDrives, setTestDrives] = useState([]);
  const [loans, setLoans] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [loading, setLoading] = useState(true);
  
  const [printingId, setPrintingId] = useState(null);
  const [showReviewModal, setShowReviewModal] = useState(false);
  const [activeReviewTd, setActiveReviewTd] = useState(null);
  const [hoverRating, setHoverRating] = useState(null);
  
  const [profileForm, setProfileForm] = useState({
    full_name: user?.full_name || '',
    phone: user?.phone || '',
  });
  const [updateStatus, setUpdateStatus] = useState(null);

  const [reviewForm, setReviewForm] = useState({
    test_drive_id: null,
    rating: 5,
    comment: ''
  });

  const fetchDashboardData = useCallback(async () => {
    try {
      setLoading(true);
      // Безопасные запросы к серверу на основе сессии/токена пользователя
      const [purchasesRes, testDrivesRes, loansRes, favoritesRes] = await Promise.all([
        api.get('/purchases/my').catch(() => ({ data: [] })),
        api.get('/test-drives/my').catch(() => ({ data: [] })),
        api.get('/loans/my').catch(() => ({ data: [] })),
        api.get('/favorites/my').catch(() => ({ data: [] }))
      ]);

      setPurchases(purchasesRes.data);
      setTestDrives(testDrivesRes.data);
      setLoans(loansRes.data);
      setFavorites(favoritesRes.data);
    } catch (err) {
      console.error("Ошибка при загрузке данных личного кабинета", err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchDashboardData();
  }, [fetchDashboardData]);

  const handleProfileUpdate = async (e) => {
    e.preventDefault();
    setUpdateStatus(null);
    try {
      const res = await api.put('/users/me', profileForm);
      setUser(res.data);
      setUpdateStatus({ type: 'success', text: 'Профиль успешно обновлен' });
    } catch (err) {
      setUpdateStatus({ type: 'error', text: err.response?.data?.detail || 'Ошибка при обновлении' });
    }
  };

  const handlePrint = (purchaseId) => {
    setPrintingId(purchaseId);
    // Даем React время отрендерить чистое окно печати перед вызовом window.print
    setTimeout(() => {
      window.print();
      setPrintingId(null);
    }, 150);
  };

  const openReviewModal = (td) => {
    setActiveReviewTd(td);
    setReviewForm({
      test_drive_id: td.id,
      rating: 5,
      comment: ''
    });
    setShowReviewModal(true);
  };

  const handleReviewSubmit = async (e) => {
    e.preventDefault();
    try {
      await api.post('/reviews', reviewForm);
      setShowReviewModal(false);
      fetchDashboardData(); // Обновляем список, чтобы скрыть кнопку отзыва
    } catch (err) {
      alert(err.response?.data?.detail || 'Ошибка при отправке отзыва');
    }
  };

  if (loading) {
    return <div className={styles.loading}>Загрузка данных личного кабинета...</div>;
  }

  return (
    <motion.div 
      className={`${styles.container} ${printingId ? styles.isPrintingBody : ''}`}
      initial={{ opacity: 0 }} 
      animate={{ opacity: 1 }}
    >
      {/* Скрытый в обычном режиме блок чека, который становится видимым только при @media print */}
      {printingId && (
        <div className={styles.invoicePrintArea}>
          {purchases.filter(p => p.id === printingId).map(purchase => (
            <div key={purchase.id} className={styles.invoiceReceipt}>
              <div className={styles.invoiceHeader}>
                <h2>LUXURY DEALER</h2>
                <p>Официальный электронный чек покупки</p>
              </div>
              <hr />
              <div className={styles.invoiceDetails}>
                <p><strong>ID Транзакции:</strong> {purchase.id}</p>
                <p><strong>Дата операции:</strong> {new Date(purchase.created_at).toLocaleString('ru-RU')}</p>
                <p><strong>Покупатель:</strong> {user?.full_name || 'Уважаемый клиент'}</p>
                <p><strong>Email:</strong> {user?.email}</p>
              </div>
              <hr />
              <div className={styles.invoiceCar}>
                <h3>Информация об автомобиле</h3>
                <p><strong>Марка / Модель:</strong> {purchase.car?.brand} {purchase.car?.model}</p>
                <p><strong>Год выпуска:</strong> {purchase.car?.year}</p>
                <p><strong>Мощность:</strong> {purchase.car?.horsepower} л.с.</p>
                <p><strong>Тип оплаты:</strong> {purchase.payment_method === 'credit' ? 'Кредитные средства' : 'Полная оплата картой'}</p>
              </div>
              <hr />
              <div className={styles.invoiceTotal}>
                <span>ИТОГО К ОПЛАТЕ:</span>
                <strong>{purchase.car?.price?.toLocaleString('ru-RU')} ₽</strong>
              </div>
              <div className={styles.invoiceFooter}>
                <p>Спасибо за выбор Luxury Dealer. Счастливого пути!</p>
                <div className={styles.signatureLine}>М.П. Подпись кассира</div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Обычный интерфейс кабинета, скрывающийся при печати */}
      <div className={styles.mainDashboardContent}>
        <h1 className={styles.title}>Личный кабинет</h1>
        
        <div className={styles.tabs}>
          <button className={`${styles.tab} ${activeTab === 'profile' ? styles.active : ''}`} onClick={() => setActiveTab('profile')}>Профиль</button>
          <button className={`${styles.tab} ${activeTab === 'purchases' ? styles.active : ''}`} onClick={() => setActiveTab('purchases')}>Покупки ({purchases.length})</button>
          <button className={`${styles.tab} ${activeTab === 'testdrives' ? styles.active : ''}`} onClick={() => setActiveTab('testdrives')}>Тест-драйвы ({testDrives.length})</button>
          <button className={`${styles.tab} ${activeTab === 'loans' ? styles.active : ''}`} onClick={() => setActiveTab('loans')}>Кредиты ({loans.length})</button>
          <button className={`${styles.tab} ${activeTab === 'favorites' ? styles.active : ''}`} onClick={() => setActiveTab('favorites')}>Избранное ({favorites.length})</button>
        </div>

        <div className={styles.tabContent}>
          {activeTab === 'profile' && (
            <motion.div className={styles.profileCard} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
              <div className={styles.profileHeaderInfo}>
                <div className={styles.avatarPlaceholder}>{user?.full_name?.charAt(0) || 'U'}</div>
                <div>
                  <h3>{user?.full_name || 'Пользователь'}</h3>
                  <p>{user?.email} • <span className={styles.roleBadge}>{user?.role}</span></p>
                </div>
              </div>

              <form onSubmit={handleProfileUpdate} className={styles.profileForm}>
                <div className={styles.formGroup}>
                  <label>ФИО</label>
                  <input type="text" value={profileForm.full_name} onChange={(e) => setProfileForm({...profileForm, full_name: e.target.value})} required />
                </div>
                <div className={styles.formGroup}>
                  <label>Телефон</label>
                  <input type="text" value={profileForm.phone} onChange={(e) => setProfileForm({...profileForm, phone: e.target.value})} placeholder="+7 (999) 000-00-00" />
                </div>
                {updateStatus && (
                  <p className={updateStatus.type === 'success' ? styles.successText : styles.errorText}>{updateStatus.text}</p>
                )}
                <button type="submit\" className={styles.saveBtn}>Сохранить изменения</button>
              </form>

              {notifications && notifications.length > 0 && (
                <div className={styles.notificationsBlock}>
                  <div className={styles.notifHeader}>
                    <h4>Уведомления</h4>
                    <button onClick={clearNotifications} className={styles.clearNotifBtn}>Очистить</button>
                  </div>
                  <div className={styles.notifList}>
                    {notifications.map((n, i) => (
                      <div key={i} className={styles.notifItem}>{n}</div>
                    ))}
                  </div>
                </div>
              )}
            </motion.div>
          )}

          {activeTab === 'purchases' && (
            <div className={styles.cardsGrid}>
              {purchases.length === 0 ? (
                <p className={styles.emptyText}>Вы еще не совершали покупок.</p>
              ) : (
                purchases.map(purchase => (
                  <motion.div key={purchase.id} className={styles.card} whileHover={{ y: -5 }}>
                    <div className={styles.cardImageWrapper}>
                      <img src={getImageUrl(purchase.car?.image_url)} alt={purchase.car?.brand} className={styles.cardImage} />
                    </div>
                    <div className={styles.cardBody}>
                      <h4>{purchase.car?.brand} {purchase.car?.model}</h4>
                      <p className={styles.price}>{purchase.car?.price?.toLocaleString()} ₽</p>
                      <div className={styles.purchaseMeta}>
                        <p>Дата: {new Date(purchase.created_at).toLocaleDateString()}</p>
                        <p>Метод: {purchase.payment_method === 'credit' ? 'Кредит' : 'Карта'}</p>
                      </div>
                      <button onClick={() => handlePrint(purchase.id)} className={styles.printBtn}>
                        🖨️ Распечатать чек
                      </button>
                    </div>
                  </motion.div>
                ))
              )}
            </div>
          )}

          {activeTab === 'testdrives' && (
            <div className={styles.cardsGrid}>
              {testDrives.length === 0 ? (
                <p className={styles.emptyText}>Нет запланированных или прошедших тест-драйвов.</p>
              ) : (
                testDrives.map(td => (
                  <motion.div key={td.id} className={styles.card} whileHover={{ y: -5 }}>
                    <div className={styles.cardImageWrapper}>
                      <img src={getImageUrl(td.car?.image_url)} alt={td.car?.brand} className={styles.cardImage} />
                    </div>
                    <div className={styles.cardBody}>
                      <h4>{td.car?.brand} {td.car?.model}</h4>
                      <div className={styles.tdDetails}>
                        <p><strong>Дата:</strong> {new Date(td.date).toLocaleDateString()}</p>
                        <p><strong>Время:</strong> {td.time}</p>
                        <p><strong>Статус:</strong> <span className={`${styles.status} ${styles[td.status]}`}>{td.status}</span></p>
                      </div>
                      {td.status === 'completed' && !td.has_review && (
                        <button onClick={() => openReviewModal(td)} className={styles.reviewBtn}>
                          Оставить отзыв
                        </button>
                      )}
                    </div>
                  </motion.div>
                ))
              )}
            </div>
          )}

          {activeTab === 'loans' && (
            <div className={styles.cardsGrid}>
              {loans.length === 0 ? (
                <p className={styles.emptyText}>У вас нет активных кредитных программ.</p>
              ) : (
                loans.map(loan => (
                  <motion.div key={loan.id} className={styles.card} whileHover={{ y: -5 }}>
                    <div className={styles.cardBody}>
                      <h4 className={styles.loanTitle}>Кредитный договор №{loan.id}</h4>
                      <div className={styles.loanMeta}>
                        <p>Сумма: <strong>{loan.amount?.toLocaleString()} ₽</strong></p>
                        <p>Срок: {loan.term_months} мес.</p>
                        <p>Ставка: {loan.interest_rate}%</p>
                        <p>Платёж: <strong>{loan.monthly_payment?.toLocaleString()} ₽/мес.</strong></p>
                      </div>
                    </div>
                  </motion.div>
                ))
              )}
            </div>
          )}

          {activeTab === 'favorites' && (
            <div className={styles.cardsGrid}>
              {favorites.length === 0 ? (
                <p className={styles.emptyText}>Список избранного пуст.</p>
              ) : (
                favorites.map(fav => (
                  <motion.div key={fav.id} className={styles.card} whileHover={{ y: -5 }}>
                    <div className={styles.cardImageWrapper}>
                      <img src={getImageUrl(fav.car?.image_url)} alt={fav.car?.brand} className={styles.cardImage} />
                    </div>
                    <div className={styles.cardBody}>
                      <h4>{fav.car?.brand} {fav.car?.model}</h4>
                      <p className={styles.price}>{fav.car?.price?.toLocaleString()} ₽</p>
                      <Link to={`/cars/${fav.car?.id}`} className={styles.viewCarLink}>Посмотреть авто →</Link>
                    </div>
                  </motion.div>
                ))
              )}
            </div>
          )}
        </div>
      </div>

      {/* Модальное окно звездного отзыва */}
      <AnimatePresence>
        {showReviewModal && (
          <motion.div className={styles.modalOverlay} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setShowReviewModal(false)}>
            <motion.div className={styles.modal} initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.9, opacity: 0 }} onClick={(e) => e.stopPropagation()}>
              <div className={styles.modalHeader}>
                <h3>Отзыв о тест-драйве</h3>
                <button onClick={() => setShowReviewModal(false)} className={styles.closeBtn}>✕</button>
              </div>
              <p className={styles.modalSubtitle}>{activeReviewTd?.car?.brand} {activeReviewTd?.car?.model}</p>
              
              <form onSubmit={handleReviewSubmit}>
                <div className={styles.modalField}>
                  <label>Ваша оценка</label>
                  <div className={styles.starsRating}>
                    {[1, 2, 3, 4, 5].map((star) => {
                      return (
                        <span 
                          key={star}
                          className={`${styles.star} ${(hoverRating || reviewForm.rating) >= star ? styles.starActive : ''}`}
                          onClick={() => setReviewForm({ ...reviewForm, rating: star })}
                          onMouseEnter={() => setHoverRating(star)}
                          onMouseLeave={() => setHoverRating(null)}
                        >
                          ★
                        </span>
                      );
                    })}
                  </div>
                </div>
                
                <div className={styles.modalField}>
                  <label>Ваш отзыв</label>
                  <textarea 
                    placeholder="Расскажите, как прошёл тест-драйв, понравилась ли управляемость и динамика автомобиля..." 
                    value={reviewForm.comment}
                    onChange={(e) => setReviewForm({ ...reviewForm, comment: e.target.value })}
                    className={styles.modalTextarea}
                    rows="4"
                    required
                  />
                </div>
                
                <div className={styles.modalActions}>
                  <button type="button" className={styles.cancelBtn} onClick={() => setShowReviewModal(false)}>
                    Отмена
                  </button>
                  <button type="submit" className={styles.submitBtn}>
                    Отправить отзыв
                  </button>
                </div>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

export default UserDashboard;
